<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{{ $brand['tagline'] }}"><title>{{ $brand['name'] }}</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><style>:root{--bg:#020a10;--panel:#061a24;--line:rgba(86,210,238,.15);--text:#effcff;--muted:#8daab5;--cyan:#43d1f0;--cyan2:#9af4ff}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 18% 0,rgba(30,166,202,.12),transparent 28%),radial-gradient(circle at 90% 35%,rgba(30,116,165,.09),transparent 30%),var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif;overflow-x:hidden}body:before{content:"";position:fixed;inset:0;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.014) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.014) 1px,transparent 1px);background-size:60px 60px;mask-image:linear-gradient(to bottom,#000,transparent 75%);animation:gridDrift 30s linear infinite}a{color:inherit;text-decoration:none}.shell{width:min(1180px,calc(100% - 28px));margin:auto}.header{position:sticky;top:0;z-index:50;background:rgba(2,10,16,.86);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.nav{height:70px;display:flex;align-items:center;justify-content:space-between;gap:15px}.brand{display:flex;align-items:center;gap:10px;font-weight:850;min-width:0}.brand img{width:40px;height:40px;object-fit:contain;border-radius:10px}.brand i{color:var(--cyan)}.brand span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.menu{display:flex;gap:3px}.menu a{font-size:10px;color:#9bb5be;padding:10px;border-radius:9px}.menu a:hover{color:#fff;background:rgba(67,209,240,.08)}.menu-btn{display:none;width:42px;height:42px;border:1px solid var(--line);border-radius:11px;background:#06141d;color:#fff}.hero{min-height:720px;display:grid;grid-template-columns:1.02fr .98fr;align-items:center;gap:45px;padding:65px 0;position:relative;isolation:isolate}.hero:before{content:"";position:absolute;z-index:-2;width:680px;height:680px;left:-300px;top:-80px;border-radius:50%;background:radial-gradient(circle,rgba(35,205,239,.12),transparent 68%);animation:heroGlow 8s ease-in-out infinite}.hero:after{content:"";position:absolute;z-index:-3;inset:-20%;background:linear-gradient(115deg,transparent 42%,rgba(86,225,249,.04) 50%,transparent 58%);transform:translateX(-65%);animation:energySweep 11s ease-in-out infinite;pointer-events:none}.hero-copy{z-index:2}.eyebrow{display:inline-flex;align-items:center;gap:9px;color:var(--cyan);font-size:9px;letter-spacing:.22em;text-transform:uppercase}.eyebrow:before{content:"";width:28px;height:1px;background:var(--cyan);box-shadow:0 0 12px var(--cyan);animation:linePulse 2.4s ease-in-out infinite}h1{font-size:clamp(45px,6vw,82px);line-height:.94;letter-spacing:-.06em;margin:18px 0}.hero p{max-width:650px;color:var(--muted);font-size:15px;line-height:1.85}.actions{display:flex;gap:9px;margin-top:28px;flex-wrap:wrap}.btn{padding:13px 17px;border-radius:11px;background:linear-gradient(135deg,#37c5e6,#147f9f);font-size:10px;font-weight:850;transition:transform .25s,box-shadow .25s}.btn:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(42,193,222,.18)}.btn.secondary{background:rgba(255,255,255,.035);border:1px solid var(--line);color:#b9d5dd}.reactor-wrap{height:500px;position:relative;display:grid;place-items:center;pointer-events:none;isolation:isolate}.reactor-glow{position:absolute;width:86%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,rgba(55,209,239,.14),transparent 65%);filter:blur(10px);animation:reactorGlow 5s ease-in-out infinite}.reactor{position:relative;width:min(430px,82vw);height:360px;filter:drop-shadow(0 20px 45px rgba(0,0,0,.35))}.cooling{position:absolute;bottom:32px;width:170px;height:250px;border:2px solid rgba(126,237,255,.75);border-top:0;border-radius:12px 12px 48% 48%/12px 12px 30% 30%;background:linear-gradient(90deg,rgba(17,63,78,.58),rgba(4,23,32,.9));box-shadow:inset 0 0 35px rgba(55,209,239,.08),0 0 30px rgba(55,209,239,.08);left:50%;transform:translateX(-50%)}.cooling:before{content:"";position:absolute;top:-2px;left:-15px;width:196px;height:34px;border:2px solid rgba(126,237,255,.75);border-radius:50%;background:#061b26}.cooling:after{content:"";position:absolute;inset:30px 28px 55px;border:1px solid rgba(126,237,255,.15);border-radius:50%;background:radial-gradient(circle,rgba(67,209,240,.12),transparent 65%)}.reactor-core{position:absolute;left:50%;top:158px;transform:translateX(-50%);width:110px;height:110px;border-radius:50%;background:radial-gradient(circle,#dffcff 0 7%,#5fe2f2 15%,#087b99 45%,rgba(2,10,16,0) 72%);box-shadow:0 0 28px #43d1f0,0 0 90px rgba(67,209,240,.35);animation:corePulse 2.6s ease-in-out infinite}.fan{position:absolute;right:28px;bottom:54px;width:92px;height:92px;border:2px solid rgba(126,237,255,.55);border-radius:50%;background:rgba(3,19,27,.82);box-shadow:0 0 25px rgba(67,209,240,.12)}.fan-blades{position:absolute;inset:15px;animation:fanSpin 2.4s linear infinite}.fan-blades:before,.fan-blades:after{content:"";position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 10deg,rgba(141,243,255,.9) 0 13%,transparent 13% 50%,rgba(141,243,255,.9) 50% 63%,transparent 63% 100%);transform:rotate(25deg)}.fan-blades:after{transform:rotate(115deg)}.fan-hub{position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);border-radius:50%;background:#c8f9ff;box-shadow:0 0 15px #43d1f0}.steam{position:absolute;left:50%;top:-12px;width:180px;height:115px;transform:translateX(-50%);filter:blur(1px)}.steam i{position:absolute;bottom:0;width:34px;height:34px;border-radius:50%;background:rgba(213,248,255,.14);box-shadow:0 0 25px rgba(153,239,255,.12);animation:smoke 4.8s ease-in-out infinite}.steam i:nth-child(1){left:32px;animation-delay:0s}.steam i:nth-child(2){left:76px;width:42px;height:42px;animation-delay:1.2s}.steam i:nth-child(3){left:118px;width:28px;height:28px;animation-delay:2.2s}.energy-line{position:absolute;left:50%;bottom:10px;width:330px;height:1px;transform:translateX(-50%);background:linear-gradient(90deg,transparent,#43d1f0,transparent);box-shadow:0 0 14px #43d1f0;opacity:.5;animation:lineFlow 2.8s ease-in-out infinite}.section{padding:85px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:25px}.section-head h2{font-size:clamp(29px,4vw,48px);letter-spacing:-.04em;margin:8px 0}.section-head p{max-width:520px;color:var(--muted);font-size:11px;line-height:1.8}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}.stat{padding:22px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(8,38,52,.8),rgba(3,21,30,.7));position:relative;overflow:hidden;animation:rise .8s both}.stat:after{content:"";position:absolute;width:80px;height:80px;border-radius:50%;right:-30px;top:-30px;background:rgba(67,209,240,.07);animation:reactorGlow 4s ease-in-out infinite}.stat i{color:var(--cyan)}.stat small{display:block;color:#688994;font-size:8px;text-transform:uppercase;letter-spacing:.14em;margin-top:18px}.stat strong{display:block;font-size:28px;margin-top:5px}.technology{display:grid;grid-template-columns:1fr 1fr;gap:18px}.tech-card{min-height:330px;padding:30px;border:1px solid var(--line);border-radius:22px;background:linear-gradient(145deg,rgba(7,31,43,.9),rgba(3,17,25,.85));position:relative;overflow:hidden}.tech-card h3{font-size:25px;margin:0 0 10px}.tech-card p{color:var(--muted);font-size:11px;line-height:1.9;max-width:520px}.bars{display:grid;gap:12px;margin-top:28px}.bar span{display:flex;justify-content:space-between;font-size:9px;color:#91adb7;margin-bottom:5px}.track{height:5px;background:rgba(255,255,255,.06);border-radius:99px;overflow:hidden}.fill{height:100%;width:var(--w);background:linear-gradient(90deg,#197d99,#5fe2f2);border-radius:99px;animation:grow 1.6s ease both}.news-grid,.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.card{padding:20px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(8,38,52,.82),rgba(3,21,30,.8));transition:.25s}.card:hover{transform:translateY(-6px);border-color:rgba(86,210,238,.35);box-shadow:0 20px 45px rgba(0,0,0,.2)}.card .icon{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;color:var(--cyan);background:rgba(67,209,240,.07);margin-bottom:18px}.card h3{font-size:17px;margin:0 0 9px}.card p,.meta{color:var(--muted);font-size:10px;line-height:1.75}.meta{margin-top:12px}.pill{display:inline-flex;margin-top:12px;padding:5px 8px;border-radius:99px;background:rgba(69,224,173,.08);color:#72dfbf;font-size:8px}.news-card{min-height:180px}.footer{border-top:1px solid var(--line);padding:32px 0 50px;color:#688893;font-size:9px}.reveal{opacity:0;transform:translateY(24px);transition:opacity .8s ease,transform .8s ease}.reveal.visible{opacity:1;transform:none}@keyframes fanSpin{to{transform:rotate(360deg)}}@keyframes smoke{0%{transform:translate(0,0) scale(.55);opacity:0}20%{opacity:.65}65%{opacity:.3}100%{transform:translate(-22px,-105px) scale(1.65);opacity:0}}@keyframes corePulse{50%{transform:translateX(-50%) scale(1.08);box-shadow:0 0 40px #43d1f0,0 0 110px rgba(67,209,240,.45)}}@keyframes reactorGlow{50%{transform:scale(1.12);opacity:.72}}@keyframes lineFlow{50%{opacity:.9;transform:translateX(-50%) scaleX(1.08)}}@keyframes gridDrift{to{background-position:60px 60px}}@keyframes heroGlow{50%{transform:scale(1.08);opacity:.7}}@keyframes energySweep{0%,15%{transform:translateX(-65%)}65%,100%{transform:translateX(65%)}}@keyframes linePulse{50%{width:38px;opacity:.5}}@keyframes grow{from{width:0}}@keyframes rise{from{opacity:0;transform:translateY(20px)}}@media(max-width:900px){.hero{grid-template-columns:1fr;min-height:auto;padding:55px 0}.reactor-wrap{height:420px;order:-1}.